import { api } from 'pages/APIs';
import AbstractApiService from 'src/services/abstractApiService';
import type { DocumentExtractionExplanations } from 'src/types/extractionExplanation';

export interface BulkDeleteResult {
  deleted_count: number;
  skipped_ids: string[];
}

/**
 * Reads the per-field extraction explanation for a document
 * (DOCB-12002 phase 2 endpoint) and deletes FellowKV rules surfaced
 * by the panel (DOCB-12181 power features).
 */
export default class ExtractionExplanationApiService extends AbstractApiService {
  public constructor({}) {
    super({});
  }

  public async getForDocument(
    docId: string,
  ): Promise<DocumentExtractionExplanations> {
    const url = `${api.get_extraction_explanations}/${encodeURIComponent(docId)}/extraction-explanations`;
    return super.get(url, {});
  }

  /**
   * Soft-delete a single FellowKV rule. Backs the per-candidate trash
   * icon. Org-scope is enforced server-side from the JWT — no body.
   */
  public async deleteRule(
    ruleId: string,
  ): Promise<{ rule_id: string; deleted: boolean }> {
    const url = `${api.fellow_kv_rules}/${encodeURIComponent(ruleId)}`;
    return super.deleteWithoutOrgId(url);
  }

  /**
   * Soft-delete many rules in one round-trip. Backs the "Cleanup all"
   * button — the panel computes the rule_ids client-side (every
   * non-winner across visible fields) so the server stays simple.
   */
  public async bulkDeleteRules(
    ruleIds: string[],
  ): Promise<BulkDeleteResult> {
    const url = `${api.fellow_kv_rules}/bulk_delete`;
    return super.postWithoutOrgId(url, { rule_ids: ruleIds });
  }
}
